#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

#define BIG_BASE UINT32_C(1000000000)
#define BIG_WIDTH UINT32_C(9)

typedef struct {
    uint32_t *limbs;
    size_t length;
    size_t capacity;
} BigInteger;

static void *xrealloc(void *pointer, size_t size)
{
    void *result = realloc(pointer, size);
    if (result == NULL) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return result;
}

static void big_initialize(BigInteger *value, uint32_t limb)
{
    value->limbs = xrealloc(NULL, sizeof *value->limbs);
    value->limbs[0] = limb;
    value->length = 1;
    value->capacity = 1;
}

static void big_reserve(BigInteger *value, size_t capacity)
{
    size_t new_capacity;

    if (capacity <= value->capacity) {
        return;
    }
    if (capacity > SIZE_MAX / sizeof *value->limbs) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }

    new_capacity = value->capacity == 0 ? 1 : value->capacity;
    while (new_capacity < capacity) {
        if (new_capacity > SIZE_MAX / 2) {
            new_capacity = capacity;
            break;
        }
        new_capacity *= 2;
    }
    if (new_capacity > SIZE_MAX / sizeof *value->limbs) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }

    value->limbs = xrealloc(value->limbs,
                            new_capacity * sizeof *value->limbs);
    value->capacity = new_capacity;
}

static void big_add(BigInteger *left, const BigInteger *right)
{
    size_t width = left->length > right->length ? left->length : right->length;
    uint32_t carry = 0;
    size_t i;

    if (width == SIZE_MAX) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    big_reserve(left, width + 1);

    for (i = 0; i < width; ++i) {
        uint64_t sum = carry;

        if (i < left->length) {
            sum += left->limbs[i];
        }
        if (i < right->length) {
            sum += right->limbs[i];
        }

        if (sum >= BIG_BASE) {
            left->limbs[i] = (uint32_t)(sum - BIG_BASE);
            carry = 1;
        } else {
            left->limbs[i] = (uint32_t)sum;
            carry = 0;
        }
    }

    left->length = width;
    if (carry != 0) {
        left->limbs[width] = carry;
        left->length = width + 1;
    }
}

static void big_print(const BigInteger *value)
{
    size_t i;

    printf("%" PRIu32, value->limbs[value->length - 1]);
    for (i = value->length - 1; i > 0; --i) {
        printf("%09" PRIu32, value->limbs[i - 1]);
    }
    putchar('\n');
}

static int parse_count(const char *text, size_t *result)
{
    size_t value = 0;

    if (*text == '+') {
        ++text;
    }
    while (text[0] == '0' && text[1] != '\0') {
        ++text;
    }
    if (*text < '0' || *text > '9') {
        return 0;
    }

    while (*text >= '0' && *text <= '9') {
        unsigned int digit = (unsigned int)(*text - '0');

        if (value > (SIZE_MAX - digit) / 10) {
            return 0;
        }
        value = value * 10 + digit;
        ++text;
    }
    if (*text != '\0') {
        return 0;
    }

    *result = value;
    return 1;
}

int main(int argc, char **argv)
{
    BigInteger a;
    BigInteger b;
    size_t n;
    size_t i;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s N\n", argv[0]);
        return EXIT_FAILURE;
    }
    if (!parse_count(argv[1], &n)) {
        fprintf(stderr, "N must be a nonnegative decimal integer\n");
        return EXIT_FAILURE;
    }

    big_initialize(&a, 0);
    big_initialize(&b, 1);
    for (i = 0; i < n; ++i) {
        BigInteger temporary;

        big_add(&a, &b);
        temporary = a;
        a = b;
        b = temporary;
    }

    big_print(&a);
    free(a.limbs);
    free(b.limbs);
    return EXIT_SUCCESS;
}
